contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "test contract needs enough balance");
        require(amount <= address(c).balance, "amount must not exceed contract balance");

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        assert(!reverted && afterBalance == beforeBalance - amount && afterDeposits == beforeDeposits && afterOwner == beforeOwner);
    }
}

